"""Render sanitized Markdown in an isolated reporting environment."""
import json,sys,re,html
import markdown,bleach

def render(text,path):
 body=markdown.markdown(text,extensions=['tables','fenced_code','toc','sane_lists'])
 body=bleach.clean(body,tags={'h1','h2','h3','h4','h5','h6','p','a','strong','em','code','pre','blockquote','ul','ol','li','table','thead','tbody','tr','th','td','hr','br','div','span'},attributes={'a':['href','title'],'code':['class'],'div':['class'],'h1':['id'],'h2':['id'],'h3':['id'],'th':['align'],'td':['align']},protocols={'http','https'},strip=True)
 body=body.replace('<table>','<div class="table-scroll"><table>').replace('</table>','</table></div>')
 name=html.escape(path);title=html.escape(next((line.lstrip('# ').strip() for line in text.splitlines() if line.startswith('# ')),path))
 style='''*{box-sizing:border-box}body{margin:0;background:#eef3f4;color:#20383f;font:16px/1.7 system-ui,sans-serif}header{background:#173e45;color:#e0efec;padding:22px max(4vw,20px)}nav{display:flex;gap:22px;flex-wrap:wrap}header a{color:#bce8db}header small{display:block;margin-top:12px;overflow-wrap:anywhere}main{max-width:1450px;margin:28px auto;padding:32px;background:white;border:1px solid #dbe4e6;border-radius:16px}h1{font-size:30px;line-height:1.3;letter-spacing:-.025em;margin:8px 0 26px}h2{font-size:23px;margin:32px 0 14px}h3{font-size:19px;margin-top:24px}p{max-width:1050px}a{color:#116e64;text-underline-offset:3px}pre{background:#152f37;color:#e1f1e9;padding:20px;border-radius:10px;white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.55;font-size:13px}code{font-family:Consolas,monospace;overflow-wrap:anywhere}p code,td code,li code{background:#edf4f2;padding:2px 4px;border-radius:4px;font-size:.9em}.table-scroll{overflow:auto;border:1px solid #dbe4e6;border-radius:10px;margin:22px 0}table{width:100%;border-collapse:collapse;font-size:14px;line-height:1.6}th,td{text-align:left;vertical-align:top;padding:15px;min-width:150px;border-bottom:1px solid #dbe4e6}th{background:#e4efec;color:#214c48}tr:nth-child(even){background:#f7faf9}blockquote{border-left:4px solid #438676;padding:2px 18px;color:#526c71}footer{font-size:13px;color:#637c80;padding-top:24px;border-top:1px solid #dbe4e6}.toc{background:#f1f6f4;border-radius:8px;padding:12px}@media(max-width:700px){main{margin:12px;padding:18px}h1{font-size:25px}th,td{min-width:160px;padding:12px}}@media print{body{background:white}header{display:none}main{border:0;margin:0;padding:0;max-width:none}a{color:inherit}pre{background:#f3f5f5;color:#152f37}.table-scroll{overflow:visible}table{font-size:10px}th,td{min-width:0;padding:7px}tr{break-inside:avoid}}'''
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+' | AEGIS</title><style>'+style+'</style></head><body><header><nav><a href="/dashboard/">Overview</a><a href="/dashboard/defects.html">Defect discovery</a><a href="/dashboard/runs.html">Test runs</a><a href="/dashboard/sdk-coverage.html">Coverage</a></nav><small>AEGIS Care / '+name+'</small></header><main>'+body+'<footer>Readable view of the saved Markdown source. Evidence links retain their original paths. Raw execution artifacts remain local.</footer></main></body></html>'
if __name__=='__main__':
 request=json.loads(sys.stdin.read());sys.stdout.reconfigure(encoding='utf-8');sys.stdout.write(render(request['text'],request['path']))
